begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into public.institutions(id,name) values('d1100000-0000-4000-8000-000000000001','[SYNTHETIC] Operations institute'),('d1100000-0000-4000-8000-000000000002','[SYNTHETIC] Other institute');
insert into public.departments(id,institution_id,name) values('d1200000-0000-4000-8000-000000000001','d1100000-0000-4000-8000-000000000001','Synthetic department'),('d1200000-0000-4000-8000-000000000002','d1100000-0000-4000-8000-000000000002','Other department');
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data) select ('d1000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'ops-'||n||'@example.test',case when n<>10 then now() end,'{"role":"administrator","verified":true}' from generate_series(1,10)n;
insert into public.profiles(user_id,display_name,claimed_kind,institution_id,department_id,joining_year,graduation_year,career_interests)
select id,'[SYNTHETIC] Operations '||right(id::text,2),case when right(id::text,2) in ('03','08') then 'staff' else 'alumni' end::public.account_kind,
case when right(id::text,2)='09' then 'd1100000-0000-4000-8000-000000000002'::uuid else 'd1100000-0000-4000-8000-000000000001'::uuid end,
case when right(id::text,2)='09' then 'd1200000-0000-4000-8000-000000000002'::uuid else 'd1200000-0000-4000-8000-000000000001'::uuid end,
case when right(id::text,2) not in ('03','08') then 2020 end,
case when right(id::text,2) not in ('03','08') then 2024 end,array['Engineering'] from auth.users where id::text like 'd1000000-%';
insert into private.memberships(user_id,status,verified_kind,updated_at)
select user_id,case right(user_id::text,2) when '03' then 'pending' when '04' then 'pending' when '06' then 'suspended' when '07' then 'rejected' when '09' then 'pending' when '10' then 'pending' else 'verified' end::public.membership_status,
case when right(user_id::text,2) in ('01','02','05') then 'alumni'::public.account_kind when right(user_id::text,2)='08' then 'staff'::public.account_kind end,'2026-01-01Z' from public.profiles where user_id::text like 'd1000000-%';
insert into private.account_roles(user_id,role) values('d1000000-0000-4000-8000-000000000001','administrator'),('d1000000-0000-4000-8000-000000000002','administrator'),('d1000000-0000-4000-8000-000000000010','administrator');
set local role anon;
select throws_ok($$select public.administration_context()$$,'42501',null,'Anonymous cannot read administrator context');
reset role;set local role authenticated;
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000003',true);
select throws_ok($$select public.administration_context()$$,'42501',null,'Pending Staff metadata never grants administrator access');
select throws_ok($$select public.decide_institutional_membership(auth.uid(),'approve','staff','record_checked','Self approve','2026-01-01Z',gen_random_uuid())$$,'42501',null,'Pending self approval denied');
select throws_ok($$select public.administration_reports()$$,'42501',null,'Direct report RPC rejects pending callers');
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000008',true);
select throws_ok($$select public.administration_members()$$,'42501',null,'Verified ordinary Staff is not an administrator');
select throws_ok($$select * from private.administration_audit$$,'42501',null,'Ordinary Staff cannot read internal audit');
select throws_ok($$insert into private.account_roles(user_id,role) values(auth.uid(),'administrator')$$,'42501',null,'Client cannot provision roles');
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000010',true);
select throws_ok($$select public.administration_context()$$,'42501',null,'Unconfirmed account with protected role still denied');
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000001',true);
select is(jsonb_array_length(public.administration_members()),3,'Pending queue includes same-institution claims only');
select is(jsonb_array_length(public.administration_members('pending','staff')),1,'Staff filter is server-side');
select is(jsonb_array_length(public.administration_members('pending',null,0,1)),1,'Page size bounded');
select is(jsonb_array_length(public.administration_members('pending',null,1,1)),1,'Next page available');
select throws_ok($$select public.administration_members('pending',null,-1,30)$$,'23514',null,'Invalid pagination denied');
select throws_ok($$select public.decide_institutional_membership('d1000000-0000-4000-8000-000000000009','approve','alumni','record_checked','Cross institution','2026-01-01Z',gen_random_uuid())$$,'42501',null,'Cross-institution review prohibited');
select throws_ok($$select * from public.verification_history('d1000000-0000-4000-8000-000000000009')$$,'42501',null,'Legacy history cannot leak across institutions');
select throws_ok($$select public.decide_institutional_membership(auth.uid(),'suspend',null,'policy_violation','Self action','2026-01-01Z',gen_random_uuid())$$,'42501',null,'Self review prohibited');
select lives_ok($$select public.decide_institutional_membership('d1000000-0000-4000-8000-000000000004','approve','alumni','record_checked','Synthetic offline evidence reviewed','2026-01-01Z','d1300000-0000-4000-8000-000000000001')$$,'Authorized approval records independent decision');
select lives_ok($$select public.decide_institutional_membership('d1000000-0000-4000-8000-000000000004','approve','alumni','record_checked','Synthetic offline evidence reviewed','2026-01-01Z','d1300000-0000-4000-8000-000000000001')$$,'Exact duplicate request is idempotent');
select is(jsonb_array_length(public.administration_history('d1000000-0000-4000-8000-000000000004')),1,'Retry creates no duplicate audit');
select is(public.administration_history('d1000000-0000-4000-8000-000000000004')->0->>'actor_id',auth.uid()::text,'Reviewer identity comes from auth.uid');
select throws_ok($$select public.decide_institutional_membership('d1000000-0000-4000-8000-000000000004','reject',null,'details_mismatch','Different request','2026-01-01Z','d1300000-0000-4000-8000-000000000001')$$,'23514',null,'Reused request key with altered decision rejected');
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000002',true);
select throws_ok($$select public.decide_institutional_membership('d1000000-0000-4000-8000-000000000004','reject',null,'details_mismatch','Stale other reviewer','2026-01-01Z',gen_random_uuid())$$,'40001',null,'Second reviewer cannot silently overwrite a stale decision');
select lives_ok($$select public.decide_institutional_membership('d1000000-0000-4000-8000-000000000003','reject',null,'evidence_unavailable','No approved evidence available','2026-01-01Z',gen_random_uuid())$$,'Pending Staff can be rejected without privilege change');
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000003',true);
select is(public.own_review_status()->>'category','evidence_unavailable','Rejected member sees only safe category');
select ok(not(public.own_review_status()?'note'),'Private reviewer note excluded from own status');
select lives_ok($$select public.request_membership_review('appeal')$$,'Rejected member may request review');
select lives_ok($$select public.request_membership_review('appeal')$$,'Duplicate open appeal does not multiply requests');
select throws_ok($$select public.directory_profiles()$$,'42501',null,'Appeal grants no community access');
select throws_ok($$delete from private.administration_audit$$,'42501',null,'User cannot erase history');
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000002',true);
select lives_ok($$select public.decide_institutional_membership('d1000000-0000-4000-8000-000000000003','correction',null,'appeal_review','Authorized corrections required',(select (x->>'revision')::timestamptz from jsonb_array_elements(public.administration_members('rejected'))x where x->>'user_id'='d1000000-0000-4000-8000-000000000003'),gen_random_uuid())$$,'Authorized correction reopens pending without verification');
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000003',true);
select ok(not(public.own_review_status()->>'request_open')::boolean,'Handled appeal is closed');
select throws_ok($$select public.directory_profiles()$$,'42501',null,'Correction remains restricted pending');
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000006',true);
select lives_ok($$select public.request_membership_review('appeal')$$,'Suspended account appeal accepted without restoration');
select throws_ok($$select public.administration_context()$$,'42501',null,'Suspended account cannot administer');
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000005',true);
insert into public.reports(target_profile_id,reason,details) values('d1000000-0000-4000-8000-000000000004','harassment','Synthetic moderation details only');
select throws_ok($$select public.administration_reports()$$,'42501',null,'Reporter cannot read private moderation queue');
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000002',true);
select ok(not(public.administration_reports()->0?'reporter_id'),'Queue omits reporter identity');
select lives_ok($$select public.decide_institutional_report((public.administration_reports()->0->>'id')::uuid,'resolved','Synthetic policy review',(public.administration_reports()->0->>'revision')::timestamptz,gen_random_uuid())$$,'Private moderation decision succeeds');
select is(jsonb_array_length(public.administration_reports()),0,'Resolved reports leave open queue');
reset role;
update private.memberships set status='suspended',verified_kind=null where user_id='d1000000-0000-4000-8000-000000000002';
set local role authenticated;
select throws_ok($$select public.administration_context()$$,'42501',null,'Old JWT identity cannot bypass administrator suspension');
reset role;
select ok((select bool_and(c.relrowsecurity) from pg_class c where c.oid in ('private.administration_audit'::regclass,'private.membership_requests'::regclass)),'New private tables retain RLS');
select ok(not has_table_privilege('authenticated','private.administration_audit','INSERT'),'Audit insertion has no direct client grant');
insert into public.opportunities(id,author_id,title,description,kind) values('d1400000-0000-4000-8000-000000000001','d1000000-0000-4000-8000-000000000004','Synthetic reported opportunity','Synthetic opportunity description for moderation tests','job');
insert into public.reports(reporter_id,target_opportunity_id,reason,details) values('d1000000-0000-4000-8000-000000000005','d1400000-0000-4000-8000-000000000001','fraud','Synthetic fraud report for controlled tests');
set local role authenticated;
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.decide_institutional_report((public.administration_reports()->0->>'id')::uuid,'archive','Synthetic fraudulent opportunity reviewed',(public.administration_reports()->0->>'revision')::timestamptz,gen_random_uuid())$$,'Explicit report decision atomically archives opportunity');
reset role;
select ok((select archived_at is not null and status='closed' from public.opportunities where id='d1400000-0000-4000-8000-000000000001'),'Reported opportunity archived without deleting history');
insert into private.membership_requests(user_id,kind,status,resolved_at) select 'd1000000-0000-4000-8000-000000000007','appeal','closed',now() from generate_series(1,3);
set local role authenticated;
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000007',true);
select throws_ok($$select public.request_membership_review('appeal')$$,'23514',null,'Appeals bounded to three per thirty days');
reset role;
update auth.users set banned_until=now()+interval '1 hour' where id='d1000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','d1000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.administration_context()$$,'42501',null,'Auth ban invalidates administrator access with old identity');
reset role;
update auth.users set banned_until=null where id='d1000000-0000-4000-8000-000000000001';
update public.profiles set institution_id='d1100000-0000-4000-8000-000000000002',department_id='d1200000-0000-4000-8000-000000000002' where user_id='d1000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.administration_context()$$,'42501',null,'Protected role does not follow a changed institutional claim');
reset role;
select * from finish();
rollback;
